/* El sistema de diseño no expone un blanco puro (#fff); las superficies de
   lectura usan el casi-blanco más claro del sistema, --bw-warm-cream, sobre el
   fondo Cold White del panel de contenido. */

.screen {
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
}

.pageTitle {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.pageSub {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.e2eeBar {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin-bottom: 14px;
  padding: 6px 10px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
  color: var(--bw-signal-green);
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
}

.e2eeBar i {
  font-size: 12px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.searchWrap {
  position: relative;
  flex: 0 1 300px;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.newContactWrap {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: 1px solid transparent;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

.primaryBtn:disabled {
  background: var(--bw-surface-mist);
  border-color: var(--bw-line-steel-strong);
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.scopeNote {
  font-size: 11px;
  font-style: italic;
  color: var(--bw-steel-mist);
}

.pageInfo {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.loadingState {
  padding: 28px 16px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  color: var(--bw-steel-mist);
  font-size: 13px;
  text-align: center;
}

.errorBox {
  padding: 14px 16px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 8px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
}

.errorText {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: 12px;
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: default;
}

.pageBtn:not(:disabled):not(.pageActive):hover {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageCtrl {
  color: var(--bw-input-placeholder);
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

