import { useEffect, useState } from 'react';
import { PAGE_SIZE, fetchThreadPage, pageCount } from '../../lib/threads';
import type { ThreadPage } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Pantalla de Lista de Hilos.
 *
 * Es la pantalla completa del panel de contenido: posee la búsqueda, la página
 * actual y la llamada a `fetchThreadPage(profile.orgId)`. `ThreadList` recibe
 * las filas ya resueltas como componente de presentación.
 *
 * `onOpenThread` existe solo como firma pública (F-118): el shell lo cablea,
 * pero MSG-02 no está en el alcance del MVP y abrir un hilo no lleva a ningún
 * sitio. La prop se recibe y se ignora a propósito.
 */

const noopThreadOpen = (): void => {
  /* MSG-02 no está en el alcance del MVP: abrir un hilo no navega. */
};

/**
 * Extrae el error real de un fallo de PostgREST.
 *
 * PostgREST no rechaza con `Error`, sino con un objeto plano `{ code, message }`
 * (p. ej. `PGRST201`). `String(e)` lo convierte en `[object Object]` y
 * `e.message` en `undefined`; aquí se extraen `code` y `message` cuando existen
 * y se pintan junto a la frase para humanos (F-020, F-128).
 */
function describeError(error: unknown): string {
  if (typeof error === 'object' && error !== null) {
    const record = error as { code?: unknown; message?: unknown };
    const code = typeof record.code === 'string' ? record.code : undefined;
    const message = typeof record.message === 'string' ? record.message : undefined;
    if (code && message) return `${code}: ${message}`;
    if (code) return code;
    if (message) return message;
  }
  if (error instanceof Error) return error.message;
  return String(error);
}

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj (F-137). */
  now?: Date | undefined;
  onOpenThread?: ((threadId: string) => void) | undefined;
}

export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [query, setQuery] = useState('');
  const [term, setTerm] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: term, page })
      .then((result) => {
        if (cancelled) return;
        setData(result);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setData(null);
        setError(describeError(err));
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, term, page]);

  const runSearch = () => {
    setTerm(query);
    setPage(1);
  };

  const total = data?.total ?? 0;
  const totalPages = pageCount(total, PAGE_SIZE);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo
        a extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves en memoria de sesión · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`${styles.searchIcon} ti ti-search`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                runSearch();
              }
            }}
          />
        </div>

        <div className={styles.newContactWrap}>
          <button type="button" className={styles.primaryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span data-testid="directorio-scope" className={styles.scopeNote}>
            Abre DIR-01, que queda fuera del MVP.
          </span>
        </div>

        <span data-testid="pag-info" className={styles.pageInfo}>
          {total} hilos · Página {page} de {totalPages}
        </span>
      </div>

      {error ? (
        <div role="alert" className={styles.errorBox}>
          <p className={styles.errorText}>No se pudieron cargar los hilos. {error}</p>
        </div>
      ) : loading ? (
        <div className={styles.loadingState}>Cargando hilos…</div>
      ) : data ? (
        <>
          <ThreadList threads={data.threads} now={now} onOpen={noopThreadOpen} />
          {data.total > 0 && (
            <div className={styles.pagination}>
              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                disabled={page <= 1}
                aria-label="Página anterior"
                onClick={() => setPage(page - 1)}
              >
                <i className="ti ti-chevron-left" aria-hidden="true" />
              </button>
              {Array.from({ length: totalPages }, (_, index) => index + 1).map(
                (pageNumber) => (
                  <button
                    key={pageNumber}
                    type="button"
                    className={`${styles.pageBtn} ${
                      pageNumber === page ? styles.pageActive : ''
                    }`}
                    aria-current={pageNumber === page ? 'page' : undefined}
                    onClick={() => setPage(pageNumber)}
                  >
                    {pageNumber}
                  </button>
                ),
              )}
              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                disabled={page >= totalPages}
                aria-label="Página siguiente"
                onClick={() => setPage(page + 1)}
              >
                <i className="ti ti-chevron-right" aria-hidden="true" />
              </button>
            </div>
          )}
        </>
      ) : null}
    </div>
  );
}

