.threadList {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.threadItem {
  border-bottom: 1px solid var(--bw-surface-mist);
}

.threadItem:last-child {
  border-bottom: none;
}

.threadButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 16px;
  row-gap: 6px;
  align-items: center;
  width: 100%;
  padding: 14px 18px;
  border: none;
  background: none;
  font-family: var(--bw-font-body);
  font-size: 14px;
  color: var(--bw-deep-steel);
  text-align: left;
  cursor: pointer;
}

.threadButton:hover {
  background: var(--bw-hover-surface);
}

.threadButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadOrg {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex: 0 0 auto;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.threadTime {
  justify-self: end;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.threadPreview {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.stateBadgeWrap {
  justify-self: end;
  max-width: 100%;
}

.stateBadge {
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 3px;
  white-space: nowrap;
}

.toneNeutral {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.toneInfo {
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.toneWarn {
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.toneSuccess {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.toneClosed {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
