import { previewLabel, relativeTime, stateTone } from '../../lib/threads';
import type { StateTone, ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * MSG-01 · Lista de hilos (componente de presentación).
 *
 * Pinta las filas exactamente en el orden que recibe: la página ya viene
 * ordenada por `last_item_at` descendente desde el servidor. Este componente no
 * carga datos, no pagina y no ordena.
 *
 * Cada hilo es un `<li>` con un `<button>` dentro (nunca un `role="button"`
 * sobre el propio `li`): así la fila conserva su rol implícito `listitem`
 * (F-131) y el botón interior es quien lleva el nombre accesible del hilo.
 */

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj (F-137). */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/**
 * Clase CSS por tono de estado. `string | undefined` a propósito (F-143): con
 * `noUncheckedIndexedAccess`, una clase que no exista en el módulo deja la fila
 * sin adorno en vez de escribir `undefined` en el atributo.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.toneNeutral,
  info: styles.toneInfo,
  warn: styles.toneWarn,
  success: styles.toneSuccess,
  closed: styles.toneClosed,
};

export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyTitle}>Todavía no tienes ninguna conversación.</p>
        <p className={styles.emptyText}>
          Usa el Directorio para contactar con otras organizaciones.
        </p>
        <div className={styles.emptyAction}>
          <button type="button" className={styles.directoryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Ir al Directorio
          </button>
          <p className={styles.directoryNote}>El Directorio queda fuera del MVP.</p>
        </div>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.threadItem}>
          <button
            type="button"
            className={styles.threadButton}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.threadTop}>
              <span className={styles.threadOrg}>{thread.counterpartyName}</span>
              <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
            </span>
            <time className={styles.threadTime} dateTime={thread.lastItemAt}>
              {relativeTime(thread.lastItemAt, now)}
            </time>
            <span className={styles.threadPreview}>{previewLabel(thread.lastItem)}</span>
            <span className={styles.stateBadgeWrap}>
              <span
                className={`${styles.stateBadge} ${TONE_CLASS[stateTone(thread.state)] ?? ''}`}
              >
                {thread.state}
              </span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
